def triples_sum_to_zero(grid_total: list) -> bool:
    grid_total.sort()  # Sort the list to make finding triplets easier
    for i in range(len(grid_total)):
        left = i + 1
        right = len(grid_total) - 1
        while left < right:
            current_sum = grid_total[i] + grid_total[left] + grid_total[right]
            if current_sum == 0:
                return True
            elif current_sum < 0:
                left += 1
            else:
                right -= 1
    return False

