def max_sum(high_field):
    n = len(high_field)
    dp_increasing = [0] * n
    dp_decreasing = [0] * n

    # Fill dp_increasing
    for i in range(n):
        max_so_far = 0
        for j in range(i):
            if high_field[i] > high_field[j]:
                max_so_far = max(max_so_far, dp_increasing[j])
        dp_increasing[i] = max_so_far + high_field[i]

    # Fill dp_decreasing
    for i in range(n-1, -1, -1):
        max_so_far = 0
        for j in range(i+1, n):
            if high_field[i] > high_field[j]:
                max_so_far = max(max_so_far, dp_decreasing[j])
        dp_decreasing[i] = max_so_far + high_field[i]

    # Calculate the maximum bitonic sum
    max_bitonic_sum = 0
    for i in range(n):
        max_bitonic_sum = max(max_bitonic_sum, dp_increasing[i] + dp_decreasing[i] - high_field[i])

    return max_bitonic_sum

