    if len(token) != len(token[0]):
        return False

    # Calculate the sum of the first row
    target_sum = sum(token[0])

    # Check if all rows have the same sum
    for row in token:
        if sum(row) != target_sum:
            return False

    # Check if all columns have the same sum
    for col_idx in range(len(token)):
        col_sum = sum([token[row][col_idx] for row in range(len(token))])
        if col_sum != target_sum:
            return False

    # Check if both diagonals have the same sum
    diagonal_sum1 = sum([token[i][i] for i in range(len(token))])
    diagonal_sum2 = sum([token[i][len(token)-1-i] for i in range(len(token))])
    if diagonal_sum1 != target_sum or diagonal_sum2 != target_sum:
        return False

    return True

