def shell_sort(power_seen):
    n = len(power_seen)
    gap = int(n / 2)

    while gap > 0:
        for i in range(gap, n):
            temp = power_seen[i]
            j = i - gap

            while j >= 0 and temp < power_seen[j]:
                power_seen[j + gap] = power_seen[j]
                j -= gap

            power_seen[j + gap] = temp

        gap //= 2

    return power_seen

