def find_Odd_Pair(batch_bit, n):
    odd_count = 0
    for i in range(n-1):
        for j in range(i+1,n):
            if (batch_bit[i] ^ batch_bit[j]) % 2 != 0: # Check if XOR is odd
                odd_count += 1
    return odd_count

