def last(label_power, x):
    l = 0
    r = len(label_power)-1
    while l <= r:
        mid = (l+r)//2
        if label_power[mid] > x:
            r = mid - 1
        elif label_power[mid] < x:
            l = mid + 1
        else:
            # If arr[mid] equals x, move right to check if there's any larger element
            l = mid + 1
    return l - 1

