def last(label_power, part_tree):
    name = 0
    seen = len(label_power)-1
    while name <= seen:
        vec_queue = (name+seen)//2
        if label_power[vec_queue] > part_tree:
            seen = vec_queue - 1
        elif label_power[vec_queue] < part_tree:
            name = vec_queue + 1
        else:
            # If arr[mid] equals x, move right to check if there's any larger element
            name = vec_queue + 1
    return name - 1

