def find_lucas(source_name):
    # Base case: the first two Lucas numbers are 2 and 1
    if source_name == 0:
        return 2
    elif source_name == 1:
        return 1

    # Recursive case: use the formula L_n = L_(n-1) + L_(n-2)
    else:
        return find_lucas(source_name-1) + find_lucas(source_name-2)

